function statusBadge(s){
  if(s==="Active") return '<span class="badge badge-good"><span class="pip"></span>Active</span>';
  if(s==="Injured") return '<span class="badge badge-warn"><span class="pip"></span>Injured</span>';
  if(s==="Reserve") return '<span class="badge badge-muted"><span class="pip"></span>Reserve</span>';
  return '<span class="badge badge-crit"><span class="pip"></span>MIA</span>';
}
var HEROES = [
  { id:"HRO-0007", name:"Silverwing", alias:"Ada Voss", cls:"Aerial", power:88, status:"Active", clear:"Tier 4", joined:"2021-03-14", missions:64, success:92, threats:38, bio:"Precision flyer. Excels at extraction and high-altitude recon. Pairs well with ground-anchor heroes on breach ops." },
  { id:"HRO-0012", name:"Dr. Ion", alias:"Marcus Reyes", cls:"Energy", power:94, status:"Active", clear:"Tier 5", joined:"2019-06-02", missions:118, success:88, threats:71, bio:"Directed-energy specialist. High output, needs a cooldown window between deployments." },
  { id:"HRO-0021", name:"Vantablack", alias:"Unknown", cls:"Psionic", power:81, status:"Reserve", clear:"Tier 3", joined:"2022-11-18", missions:29, success:79, threats:14, bio:"Stealth and misdirection. Prefers solo infiltration; low profile by design." },
  { id:"HRO-0033", name:"Aurora Vale", alias:"Lena Park", cls:"Cosmic", power:97, status:"Active", clear:"Tier 5", joined:"2018-01-27", missions:151, success:90, threats:96, bio:"Cosmic-tier heavy hitter. Reserved for tier-4 and tier-5 threat responses only." },
  { id:"HRO-0040", name:"Magnetar", alias:"Idris Kane", cls:"Enhanced", power:76, status:"Injured", clear:"Tier 3", joined:"2020-09-09", missions:57, success:84, threats:33, bio:"Magnetic-field control. Currently on medical hold after Harbor Breach." },
  { id:"HRO-0044", name:"The Tinkerer", alias:"Sam Okafor", cls:"Tech", power:69, status:"Active", clear:"Tier 2", joined:"2023-04-21", missions:22, success:95, threats:9, bio:"Gadget and drone support. Force multiplier on any team; rarely deployed alone." },
  { id:"HRO-0051", name:"Halcyon", alias:"Priya Nair", cls:"Psionic", power:85, status:"Active", clear:"Tier 4", joined:"2020-02-15", missions:73, success:87, threats:41, bio:"Crowd-calming empath. De-escalation specialist for civilian-dense operations." },
  { id:"HRO-0058", name:"Rift", alias:"Classified", cls:"Cosmic", power:91, status:"Reserve", clear:"Tier 4", joined:"2021-08-30", missions:44, success:82, threats:52, bio:"Short-range teleport. Powerful but unstable; flagged for supervised deployment." },
  { id:"HRO-0063", name:"Ember Cho", alias:"Jae Cho", cls:"Energy", power:78, status:"Active", clear:"Tier 3", joined:"2022-05-11", missions:48, success:86, threats:27, bio:"Thermal projection. Strong area control, watch collateral on urban ops." },
  { id:"HRO-0070", name:"Null", alias:"Unknown", cls:"Mutant", power:83, status:"MIA", clear:"Tier 4", joined:"2019-12-01", missions:66, success:80, threats:59, bio:"Power-nullification field. Last seen during Operation Nightfall; status unresolved." },
  { id:"HRO-0075", name:"Grond", alias:"Boris Volkov", cls:"Enhanced", power:72, status:"Active", clear:"Tier 2", joined:"2023-01-19", missions:31, success:90, threats:18, bio:"Raw strength and durability. The wall the rest of the team stands behind." },
  { id:"HRO-0081", name:"Ms. Meridian", alias:"Grace Bello", cls:"Tech", power:80, status:"Active", clear:"Tier 3", joined:"2021-10-05", missions:59, success:89, threats:36, bio:"Tactical AI handler. Coordinates multi-hero ops from the field." }
];
var ABILITIES = { Aerial:["Flight","Wind shear","Aerial recon"], Energy:["Beam projection","Overcharge","Shielding"], Psionic:["Telepathy","Misdirection","Empathic calm"], Tech:["Drone swarm","Field repair","Tac-net"], Mutant:["Nullification","Regeneration","Adaptation"], Cosmic:["Gravity control","Stellar burst","Phase shift"], Enhanced:["Super strength","Durability","Magnetism"] };

function initials(name){ var p=name.replace(/^(Dr\.|Ms\.|The)\s+/,"").split(" "); return (p[0][0]+(p[1]?p[1][0]:p[0][1]||"")).toUpperCase(); }
function powerColor(v){ return v>=90 ? "var(--accent)" : v>=78 ? "var(--good)" : "var(--info)"; }

// ---------- Theme ----------
var root = document.documentElement, sun = document.querySelector(".ico-sun"), moon = document.querySelector(".ico-moon");
function prefersDark(){ return window.matchMedia && window.matchMedia("(prefers-color-scheme: dark)").matches; }
function isDark(){ var t = root.getAttribute("data-theme"); return t ? t==="dark" : prefersDark(); }
function paintThemeIcon(){ var d=isDark(); if(sun) sun.hidden=d; if(moon) moon.hidden=!d; }
try { var saved=localStorage.getItem("hoc-theme"); if(saved) root.setAttribute("data-theme", saved); } catch(e){}
paintThemeIcon();
document.getElementById("themeToggle").addEventListener("click", function(){
  var next = isDark() ? "light" : "dark";
  root.setAttribute("data-theme", next);
  try { localStorage.setItem("hoc-theme", next); } catch(e){}

